import{c as a,Q as r,j as o,m as t}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"When Less is More: The LLM Scaling Paradox in Context Compression","description":"","frontmatter":{"url":"https://arxiv.org/abs/2602.09789","title":"When Less is More: The LLM Scaling Paradox in Context Compression","archived_date":"2026-07-17T00:00:00.000Z","arxiv_id":2602.09789,"authors":["Ruishan Guo","Yibing Liu","Guoxin Ma","Yan Wang","Yueyang Zhang","Long Xia","Kecheng Chen","Zhiyuan Sun","Daiting Shi"],"domains":["cs.LG"],"html":"https://arxiv.org/html/2602.09789v1","pdf_path":"pdfs/2602.09789.pdf","published_date":"2026-02-10T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-02-10-llm-scaling-paradox-context-compression-2602-09789.md","filePath":"research/papers/2026-02-10-llm-scaling-paradox-context-compression-2602-09789.md","lastUpdated":1785909234000}'),s={name:"research/papers/2026-02-10-llm-scaling-paradox-context-compression-2602-09789.md"};function i(n,e,l,c,h,d){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="when-less-is-more-the-llm-scaling-paradox-in-context-compression" tabindex="-1">When Less is More: The LLM Scaling Paradox in Context Compression <a class="header-anchor" href="#when-less-is-more-the-llm-scaling-paradox-in-context-compression" aria-label="Permalink to &quot;When Less is More: The LLM Scaling Paradox in Context Compression&quot;">​</a></h1><p><strong>Authors</strong>: Ruishan Guo, Yibing Liu, Guoxin Ma, Yan Wang, Yueyang Zhang, Long Xia, Kecheng Chen, Zhiyuan Sun, Daiting Shi <strong>Published</strong>: February 10, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2602.09789" target="_blank" rel="noreferrer">https://arxiv.org/abs/2602.09789</a> · <a href="https://arxiv.org/html/2602.09789v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2602.09789 <strong>Categories</strong>: cs.LG <strong>PDF</strong>: <a href="https://arxiv.org/abs/2602.09789" target="_blank" rel="noreferrer">research/papers/pdfs/2602.09789.pdf</a></p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>（WebFetch 取得為摘述版，逐字全文未取得；以下為抓取內容）The paper challenges the assumption that larger models compress better. In a compressor-decoder lossy context compression framework, the authors identify a &quot;Size-Fidelity Paradox&quot;: expanding compressor size can reduce the accuracy of reconstructed contexts even when reconstruction error decreases. Across 27 experimental configurations, two mechanisms emerge: &quot;knowledge overwriting&quot; (larger models substitute source facts with their own learned patterns, e.g. &quot;white strawberry&quot; → &quot;red strawberry&quot;) and &quot;semantic drift&quot; (larger models rephrase/reorganize rather than reproduce, e.g. &quot;Alice hit Bob&quot; → &quot;Bob hit Alice&quot;). Mid-sized compressors frequently outperform larger ones; larger models distribute information across broader semantic spaces, creating ambiguous encodings vulnerable to modification. Scaling laws break down when the goal shifts from plausible generation to faithful preservation.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 Size-Fidelity Paradox：壓縮器模型愈大，重建 context 的忠實度反而可能下降（即使 reconstruction error 下降）</li><li>識別兩種失真機制：knowledge overwriting（大模型用自身先驗覆蓋 source 事實）與 semantic drift（改寫/重組而非忠實重現）</li><li>指出 scaling law 在「plausible generation → faithful preservation」目標切換時失效</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>27 組實驗配置中 paradox 持續成立；中型壓縮器常勝過大型</li><li>大模型將資訊分散到更廣語義空間 → 編碼模糊、易被改寫、恢復力弱</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>abstract 未列具體模型家族與規模區間，paradox 的規模邊界未知</li><li>聚焦 compressor-decoder 重建任務，對 agent 場景「摘要供下游決策」的外推需驗證</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>直接挑戰「壓縮任務升檔位更保真」的直覺——對 <code>.claude/skills/output-compress</code> 的檔位上限設計是關鍵證據：壓縮/摘要類機械任務用 cost 檔可能不只省錢還更忠實（knowledge overwriting 在強模型更嚴重）。</li><li>knowledge overwriting 即 core.md「數字對帳雙向」防的失真型態；支持機械失真閘用確定性比對而非 LLM 自評。⚠️ 單篇證據，改動檔位策略前需與 model-profiles.md eval baselines 對照。</li></ul>',16)])])}const g=a(s,[["render",i]]);export{p as __pageData,g as default};
